def transform(grid):
    # Transform each framed rectangle into its periodic checker interior, keeping its border.
    from collections import Counter
    h,w=len(grid),len(grid[0])
    colors=set(x for row in grid for x in row)-{0}
    # Find connected components by color (all borders connected); their bounds define frames.
    comps=[]
    for c in colors:
        seen=set()
        for r in range(h):
            for col in range(w):
                if grid[r][col]!=c or (r,col) in seen: continue
                stack=[(r,col)]; seen.add((r,col)); pts=[]
                while stack:
                    y,x=stack.pop(); pts.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(y+dy,x+dx)
                        if 0<=q[0]<h and 0<=q[1]<w and q not in seen and grid[q[0]][q[1]]==c:
                            seen.add(q); stack.append(q)
                comps.append((c,pts))
    out=[row[:] for row in grid]
    for c,pts in comps:
        ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
        t,b,l,rr=min(ys),max(ys),min(xs),max(xs)
        # Interior pattern: infer checker orientation from scattered same-color marks inside frame.
        marks=[(y,x) for y,x in pts if t<y<b and l<x<rr]
        if not marks: continue
        parity=Counter((y+x)%2 for y,x in marks).most_common(1)[0][0]
        for y in range(t+1,b):
            for x in range(l+1,rr):
                if (y+x)%2==parity: out[y][x]=c
    return out
